const D = { energy:.6, scale:1, hue:330, speed:1, density:.5, x:.5, y:.58, flare:.5, pomp:.5, pose:'swivel', style:'vegas', act:'solo', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- helpers ----
const u = Math.min(width, height);
const s = u * 0.0015 * P.scale;
const L = (a, b, t) => a + (b - a) * t;
const fr = i => { const v = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return v - Math.floor(v); };

// ---- seed/density-keyed structures: rhinestones ----
if (S.seedUsed !== P.seed || S.densUsed !== P.density) {
  S.seedUsed = P.seed; S.densUsed = P.density;
  S.gems = [];
  const ng = 4 + Math.round(P.density * 12);
  for (let i = 0; i < ng; i++) {
    const gy = 16 + fr(i + 21) * 52;
    const hw = L(26, 18, (gy - 16) / 52) * .8;
    S.gems.push({ x: (fr(i + 61) * 2 - 1) * hw, y: gy, d: 2.6 + fr(i + 81) * 3 });
  }
}

// ---- clock derivations ----
const bt = K.beat * P.speed;
const ph = ((bt % 1) + 1) % 1;
const pulse = Math.pow(1 - ph, 3);
const kick = Math.min(1, K.pulse * .6 + A.bass * .8);
const step = Math.floor(bt);
const wob = Math.sin(K.t * .21);

// ---- act -> pose + energy envelope ----
let pose = P.pose, em = 1;
if (P.act === 'medley') {
  const seq = ['idle','swivel','rubberlegs','swivel','windmill','swivel','kneedrop','swivel'];
  pose = seq[((K.section % 8) + 8) % 8];
  em = .55 + K.intensity * .65;
} else if (P.act === 'finale') {
  const sec = ((K.section % 8) + 8) % 8;
  pose = sec < 1 ? 'idle' : sec < 3 ? 'swivel' : sec < 5 ? 'rubberlegs' : sec < 6 ? 'windmill' : 'kneedrop';
  em = .5 + sec * .08;
}
const E = Math.min(1, Math.max(0, P.energy * em));

// ---- choreography rig ----
let swivHip = 0, swivTor = 0, bob = 0, crouch = 0, stance = 0,
    la1 = -.2, la2 = -.2, ra1 = -.15, ra2 = -.1, legL = 0, legR = 0,
    headNodv = 0, headTiltv = 0, mic = false, sing = false, point = 0, trail = false;

if (pose === 'swivel') {
  const sway = Math.sin(bt * Math.PI);
  swivHip = sway * .38 * E;
  swivTor = -sway * .22 * E;
  bob = (-Math.abs(sway) * 3.5 - pulse * 2.5 * E) * s;
  legR = (step % 2 !== 0) ? Math.sin(ph * Math.PI) * .55 * E : 0;   // knee kick on offbeats
  legL = -swivHip * .3;
  const t8 = ((bt % 8) + 8) % 8;                                    // 8-beat arm phrase:
  if (t8 >= 7) { ra1 = L(-.5, .7, t8 - 7); }                        // wind up behind...
  else if (t8 < 1) { ra1 = -2.65 + Math.pow(1 - t8, 3) * .5; point = 1 - t8; }  // ...strike up on the one
  else { ra1 = -.5 + Math.sin(bt * 1.5708) * .3; }
  ra2 = -.15;
  la1 = -1.7 + Math.sin(K.t * 1.3) * .05; la2 = -1.0;               // mic to the lips
  mic = true; sing = ph < .35;
  headNodv = pulse * .18 * E; headTiltv = sway * .06;
} else if (pose === 'idle') {
  bob = Math.sin(K.t * 1.2) * 2 * s;
  swivHip = Math.sin(K.t * .4) * .05; swivTor = -swivHip * .5;
  const c16 = (((bt / 16) % 1) + 1) % 1;                            // combs his hair every 4 bars
  if (c16 < .15) { const q = Math.sin(c16 / .15 * Math.PI); ra1 = L(-.15, -2.35, q); ra2 = L(-.1, -1.2, q); }
  else { ra1 = -.15 + Math.sin(K.t * .8) * .06; ra2 = -.1; }
  la1 = -.2 + Math.sin(K.t * .9) * .04; la2 = -.25;
  mic = true; sing = false;                                          // mic held low, crooner at rest
  headNodv = K.pulse * .07 * E; headTiltv = Math.sin(K.t * .3) * .04;
} else if (pose === 'windmill') {
  ra1 = -bt * Math.PI * (.5 + E * .7); ra2 = -.12; trail = true;    // continuous windmill
  la1 = 1.35; la2 = .3;
  legL = -.28 * E; legR = .28 * E; stance = 8 * s * E;
  crouch = 6 * s * E; bob = -pulse * 3 * s * E;
  swivTor = -.12; swivHip = .05;
  headTiltv = -.08; headNodv = pulse * .15 * E;
} else if (pose === 'kneedrop') {
  const c4 = (((bt / 4) % 1) + 1) % 1;
  let dropT = c4 < .2 ? c4 / .2 : (c4 < .65 ? 1 : (c4 < .9 ? 1 - (c4 - .65) / .25 : 0));
  const dE = dropT * dropT * (3 - 2 * dropT);
  crouch = dE * 30 * s;
  legL = dE * .95; legR = -dE * .3;
  const hold = (c4 >= .2 && c4 < .65) ? 1 : 0;
  ra1 = L(-.4, -2.7, dE); ra2 = -.1; point = hold;
  la1 = L(-.2, 1.2, dE); la2 = .2;
  headNodv = -dE * .25;
  swivTor = dE * .1;
  mic = false; sing = hold === 1 && ph < .4;
} else if (pose === 'rubberlegs') {
  const jig = Math.sin(bt * 6.2832) * E;                            // double-time leg wobble
  legL = jig * .3; legR = -jig * .3;
  swivHip = jig * .1; swivTor = -jig * .06;
  bob = -Math.abs(jig) * 2.5 * s;
  la1 = 1.1 + jig * .15; la2 = .4;
  ra1 = -1.1 + jig * .15; ra2 = -.4;
  headTiltv = jig * .05; headNodv = pulse * .12 * E;
}

// ---- palette + morphs ----
const hb = ((P.hue % 360) + 360) % 360;
const st = P.style;
const lw = Math.max(1, u * .0032);
const flareW = 8 + 18 * P.flare;
const pompH = .7 + P.pomp * .6;
const suit = st === 'neon' ? [hb, 45, 13] : st === 'velvet' ? [hb, 18, 42] : [0, 0, 97];
const suitSh = st === 'neon' ? [hb, 50, 10] : st === 'velvet' ? [hb, 22, 34] : [0, 0, 86];
const skin = st === 'neon' ? [hb, 40, 16] : st === 'velvet' ? [28, 26, 55] : [28, 38, 88];
const dark = st === 'velvet' ? [hb, 30, 18] : [0, 0, 10];

function F(c, a) {
  a = a == null ? 100 : a;
  if (st === 'neon') { fill(c[0], c[1], c[2], a); stroke(hb, 85, 100, Math.min(a, 90)); strokeWeight(lw); }
  else if (st === 'comic') { fill(c[0], Math.min(c[1] * 1.1, 95), c[2], a); stroke(0, 0, 12, a); strokeWeight(lw); }
  else { noStroke(); fill(c[0], c[1], c[2], a); }
}

const gold = st === 'neon' ? [hb, 70, 100] : [45, 85, 95];
const cx = P.x * width + wob * u * .01;
const cy = P.y * height;

push();
translate(cx, cy);

// spotlight aura
blendMode(ADD);
noStroke();
const auraR = u * (.16 + .08 * E) * (1 + A.rms * .8) * (1 + Math.sin(K.t * .7) * .05) + kick * u * .015;
fill(st === 'vegas' || st === 'comic' ? 45 : hb, 45, 95, 6 + K.intensity * 8 + kick * 5);
ellipse(0, 20 * s, auraR * 1.9, auraR * 2.3);
blendMode(BLEND);

// ground shadow
fill(0, 0, 0, 36);
ellipse(0, 114 * s, (70 + P.flare * 20) * s + stance * 2, 12 * s);

translate(0, bob + crouch);

// ---- lower body: legs + belt (hip group swivels) ----
push(); translate(0, 66 * s); rotate(swivHip);
function leg(side, rot, kickA) {
  push(); translate(side * (8 * s + stance), 0); rotate(side * rot + kickA);
  F(suit); ellipse(0, 12 * s, 17 * s, 30 * s);                       // thigh
  F(suit);                                                           // bell-bottom flare
  beginShape();
  vertex(-7 * s, 22 * s); vertex(7 * s, 22 * s);
  vertex(flareW * s, 46 * s); vertex(-flareW * s, 46 * s);
  endShape(CLOSE);
  if (st === 'vegas' || st === 'velvet') {                           // side stripe
    noStroke(); fill(gold[0], gold[1], gold[2], 80);
    beginShape(); vertex(5 * s, 22 * s); vertex(7 * s, 22 * s); vertex(flareW * s, 46 * s); vertex(flareW * s - 3 * s, 46 * s); endShape(CLOSE);
  }
  F(dark); ellipse(side * 3 * s, 47 * s, 24 * s, 8 * s);             // shoe
  pop();
}
leg(-1, .06, legL);
leg(1, -.06, -legR);
// belt + buckle
F(gold); rect(-16 * s, -4 * s, 32 * s, 7 * s, 2 * s);
noStroke(); fill(gold[0], 40, 100, 55 + kick * 45);
rect(-5 * s, -4 * s, 10 * s, 7 * s, 2 * s);
pop();

// ---- torso group (counter-swivels) ----
push(); rotate(swivTor);
// jumpsuit torso
F(suit);
beginShape(); vertex(-30 * s, 10 * s); vertex(30 * s, 10 * s); vertex(22 * s, 72 * s); vertex(-22 * s, 72 * s); endShape(CLOSE);
// side shading
if (st !== 'comic') { noStroke(); fill(suitSh[0], suitSh[1], suitSh[2], 70); beginShape(); vertex(14 * s, 10 * s); vertex(30 * s, 10 * s); vertex(22 * s, 72 * s); vertex(12 * s, 72 * s); endShape(CLOSE); }
// comic halftone dots
if (st === 'comic') {
  noStroke(); fill(230, 25, 30, 25);
  for (let r = 0; r < 5; r++) for (let c = 0; c < 5; c++) {
    const yy = (18 + r * 11) * s;
    const hw = L(27, 20, r / 4) * s;
    ellipse(-hw + (c + .5) * (hw * 2 / 5) + (r % 2) * 2 * s, yy, 2.4 * s, 2.4 * s);
  }
}
// giant collar
F(suit);
beginShape(); vertex(-30 * s, 10 * s); vertex(0, 4 * s); vertex(-6 * s, 30 * s); endShape(CLOSE);
beginShape(); vertex(30 * s, 10 * s); vertex(0, 4 * s); vertex(6 * s, 30 * s); endShape(CLOSE);
// v-neck + scarf
F(skin); triangle(-6 * s, 6 * s, 6 * s, 6 * s, 0, 22 * s);
F([hb, 75, 90]); beginShape(); vertex(-6 * s, 6 * s); vertex(6 * s, 6 * s); vertex(0, 40 * s); endShape(CLOSE);
// rhinestones — seeded, twinkle on treble + their own clock
noStroke();
for (let i = 0; i < S.gems.length; i++) {
  const g = S.gems[i];
  const tw = fr(i * 7 + Math.floor((K.t + P.seed) * 2.2)) > .76 || A.treble > .45;
  fill(hb, st === 'vegas' ? 60 : 80, 95, 90);
  ellipse(g.x * s, g.y * s, g.d * s, g.d * s);
  if (tw) {
    blendMode(ADD);
    fill(0, 0, 100, 70);
    ellipse(g.x * s, g.y * s, g.d * 1.8 * s, g.d * 1.8 * s);
    stroke(0, 0, 100, 55); strokeWeight(Math.max(1, u * .001));
    line((g.x - g.d * 1.6) * s, g.y * s, (g.x + g.d * 1.6) * s, g.y * s);
    line(g.x * s, (g.y - g.d * 1.6) * s, g.x * s, (g.y + g.d * 1.6) * s);
    noStroke(); blendMode(BLEND);
  }
}

// ---- head group ----
push(); translate(0, headNodv * 8 * s); rotate(headTiltv);
// sideburns behind face edges
F(dark); ellipse(-21 * s, -8 * s, 9 * s, 24 * s); ellipse(21 * s, -8 * s, 9 * s, 24 * s);
// face
F(skin); ellipse(0, -14 * s, 44 * s, 50 * s);
// ear hints
F(skin); ellipse(-22 * s, -14 * s, 7 * s, 12 * s); ellipse(22 * s, -14 * s, 7 * s, 12 * s);
// pompadour (morphable height)
F(dark);
arc(0, -24 * s, 60 * s, 66 * s, Math.PI, Math.PI * 2, CHORD);
ellipse(-30 * s, -30 * s, 22 * s, 30 * s);
ellipse(30 * s, -30 * s, 22 * s, 30 * s);
ellipse(0, (-40 - 12 * pompH) * s, 40 * s, (20 + 14 * pompH) * s);
ellipse(14 * s, (-38 - 10 * pompH) * s, 24 * s, (14 + 8 * pompH) * s);   // quiff curl
// sunglasses
F([0, 0, 8]); rect(-22 * s, -18 * s, 44 * s, 10 * s, 4 * s);
noStroke(); fill(0, 0, 5); ellipse(-13 * s, -16 * s, 15 * s, 10 * s); ellipse(13 * s, -16 * s, 15 * s, 10 * s);
fill(0, 0, 100, 22 + A.treble * 55 + K.pulse * 20);                     // lens glint
ellipse(-16 * s, -18 * s, 4 * s, 2.5 * s); ellipse(10 * s, -18 * s, 4 * s, 2.5 * s);
// nose + curled lip
noStroke(); fill(skin[0], skin[1] + 8, skin[2] - 8); ellipse(0, -7 * s, 7 * s, 9 * s);
if (sing) { fill(20, 60, 45); ellipse(0, 2 * s, 9 * s, (5 + pulse * 7) * s); }
else { noFill(); stroke(20, 50, 35); strokeWeight(Math.max(1, u * .0015)); arc(1 * s, 2 * s, 12 * s, 6 * s, .2, Math.PI * .75); noStroke(); }
pop(); // head

// ---- arms (two segments, drawn over torso) ----
function arm(side, a1, a2, hasMic, pt) {
  push(); translate(side * 28 * s, 14 * s); rotate(a1);
  F(suit); ellipse(0, 11 * s, 13 * s, 26 * s);                       // upper arm
  translate(0, 22 * s); rotate(a2);
  F(suit); ellipse(0, 10 * s, 11 * s, 24 * s);                       // forearm
  F(suit); ellipse(0, 17 * s, 14 * s, 8 * s);                        // flared cuff
  F(skin); ellipse(0, 23 * s, 9 * s, 9 * s);                         // hand
  if (hasMic) {
    noStroke(); fill(0, 0, 25); rect(0, 21 * s, 10 * s, 4 * s, 2 * s);
    fill(0, 0, 18); ellipse(13 * s, 23 * s, 9 * s, 9 * s);
    fill(0, 0, 60, 70); ellipse(11.5 * s, 21.5 * s, 3 * s, 3 * s);
  }
  if (pt > .1) {                                                     // pointing hand glow
    blendMode(ADD); noStroke();
    fill(gold[0], 70, 100, pt * 70);
    ellipse(0, 26 * s, 8 * s, 8 * s);
    blendMode(BLEND);
  }
  pop();
}
arm(-1, la1, la2, mic, 0);
arm(1, ra1, ra2, false, point);

// windmill hand trail (analytic ghost positions)
if (trail) {
  blendMode(ADD); noStroke();
  for (let i = 1; i <= 4; i++) {
    const g = ra1 + i * .38;
    fill(hb, 60, 100, 34 - i * 7);
    ellipse(28 * s - Math.sin(g) * 40 * s, 14 * s + Math.cos(g) * 40 * s, 8 * s, 8 * s);
  }
  blendMode(BLEND);
}
pop(); // torso group

// music notes rising while singing at the mic
if (mic && (pose === 'swivel')) {
  blendMode(ADD); noStroke();
  for (let i = 0; i < 3; i++) {
    const q = ((K.t * .22 + i * .333) % 1 + 1) % 1;
    const nx = (10 + Math.sin(K.t * 2 + i * 2.1) * 6) * s + q * 26 * s;
    const ny = -34 * s - q * 66 * s;
    const al = 60 * Math.sin(q * Math.PI);
    fill(gold[0], 60, 100, al);
    ellipse(nx, ny, 5 * s, 4 * s);
    stroke(gold[0], 60, 100, al); strokeWeight(Math.max(1, u * .0015));
    line(nx + 2.4 * s, ny, nx + 2.4 * s, ny - 9 * s);
    noStroke();
  }
  blendMode(BLEND);
}

// velvet rim light — airbrushed hue glow down one side
if (st === 'velvet') {
  blendMode(ADD); noStroke();
  fill(hb, 65, 95, 12);
  ellipse(-16 * s, 24 * s, 44 * s, 120 * s);
  fill(hb, 55, 100, 10);
  ellipse(-12 * s, -20 * s, 30 * s, 44 * s);
  blendMode(BLEND);
}

blendMode(BLEND);
pop();
